/* Festival Rescue interface. The engine owns puzzle rules; this file owns play and presentation. */
window.TryvoRescue=(()=>{
 'use strict';
 const C=window.TryvoCampaign,E=window.TryvoRescueEngine,Q=window.TryvoJourneyPuzzles,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let host,travel=null,playing=false,focusCell=null,flash='',recovered=false,showTrace=false,fitTown=false,resumeAt=null;
 const icons={tram:'<rect x="4" y="3" width="16" height="17" rx="5"/><path d="M7 7h10v6H7zM8 20l-2 3m10-3 2 3"/><circle cx="8" cy="17" r="1"/><circle cx="16" cy="17" r="1"/>',flag:'<path d="M5 22V3m0 1h13l-3 4 3 4H5"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v2"/>',bolt:'<path d="m14 2-9 12h7l-2 8 9-13h-7z"/>',undo:'<path d="m8 4-5 5 5 5M3 9h10a7 7 0 0 1 0 14"/>',play:'<path d="m8 4 12 8-12 8z"/>',check:'<path d="m4 12 5 5L20 6"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',refresh:'<path d="M20 8a9 9 0 1 0 1 7M20 2v7h-7"/>'};
 const icon=(id)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.star}</svg>`;
 const button=(text,action,extra='',secondary=false)=>`<button class="rescue-button ${secondary?'rescue-secondary':''}" data-rescue="${action}" ${extra}>${text}</button>`;
 function state(){const s=host.getState();if(!E.valid(s.tram)){if(s.tram)recovered=true;s.tram=E.fresh();}return s.tram;}
 function current(){const s=state();if(!E.unlocked(s,s.selected)||!C.available(host.getState(),s.selected))s.selected=E.levels[0].id;const l=C.routeLevel(host.getState(),E.level(s.selected));s.drafts[l.id]||=E.draft(l);Q.ensure(s.drafts[l.id]);return {s,l,d:s.drafts[l.id]};}
 function cancel(){travel?.cancel();travel=null;playing=false;}
 function configure(api){host=api;}
 function scene(lit=false){return `<img class="festival-illustration ${lit?'festival-lit':''}" src="assets/festival-town.png" alt="A lantern-lit mountain town, a river crossing and a festival waiting for its guests" width="1536" height="1024">`;}
 function home(){
  const s=state(),done=E.levels.filter(l=>E.completed(s,l.id)).length,next=E.levels.find(l=>!E.completed(s,l.id))||E.levels[2],saved=s.drafts[s.selected],resumable=saved?.path.length>1&&!E.completed(s,s.selected);
  return `<section class="poster-intro"><div><h1>Try. Learn. Own it.</h1><p>A playable world where your decisions move the story forward.</p></div><span class="intro-note">A little more<br><strong>“I did that.”</strong></span></section>
  <section class="play-hero"><div class="hero-title"><span class="festival-label">Tonight’s adventure</span><h2>Festival Rescue</h2><p>Can you bring everyone to the festival?</p></div><a class="hero-world" href="#rescue" aria-label="Open Festival Rescue and plan your route">${scene(done===3)}<span class="preview-map-title">${icon('tram')} Festival Rescue</span><span class="preview-pin depot-pin">${icon('tram')}<small>Depot</small></span><span class="preview-pin festival-pin">${icon('flag')}<small>Festival</small></span><span class="map-preview-cta">Enter the town ${icon('play')}</span></a><div class="play-hero-copy"><div class="dispatch-character"><span class="mira-avatar">${window.TryvoArt.portrait()}</span><div><strong>A message from Mira</strong><span>Festival organiser</span></div></div><h3>The lanterns are ready.<br>Their makers are stranded.</h3><p>Connect the streets, collect the riders and reach the festival within nine repair credits.</p><ol class="home-loop"><li><b>1</b><span><strong>Your plan</strong>Choose which streets to connect.</span></li><li><b>2</b><span><strong>Visible consequences</strong>Run the tram. See what needs to change.</span></li><li><b>3</b><span><strong>Your contribution</strong>See the choices behind the arrival.</span></li></ol><div class="play-hero-actions">${button((resumable?'Resume your route':done===3?'Revisit Festival Rescue':'Play Festival Rescue')+icon('play'),'enter',`data-level="${resumable?s.selected:next.id}"`)}<a href="#mission-library" class="hero-secondary">Explore the investigation missions</a></div><div class="hero-facts"><span>${icon('check')} No timer. Your pace.</span><span>${done} of 3 chapters restored</span></div></div></section>
  <section class="play-path"><div class="path-heading"><div><h2>One town. Three chapters.</h2><p>Each new arrival starts with a choice you make.</p></div><span class="caption">Your progress stays on this device</span></div><div class="episode-cards">${E.levels.map((l,i)=>{const complete=E.completed(s,l.id),open=E.unlocked(s,l.id);return `<button class="episode-card episode-${i}" data-rescue="enter" data-level="${l.id}" ${open?'':'disabled'}><span class="episode-symbol">${icon(complete?'check':open?i===0?'tram':i===1?'people':'bolt':'lock')}</span><span class="episode-copy"><small>Chapter ${i+1}${complete?' · Restored':''}</small><strong>${l.name}</strong><span>${['Find a way around the closure','Bring two groups together','Open the bridge. Connect the town.'][i]}</span></span><span class="episode-arrow">${open?'↗':'Locked'}</span></button>`;}).join('')}</div></section>`;
 }
 function label(l,id){const stop=l.stops.find(s=>s.at===id);return id===l.obstruction?'Repairable obstruction':id===l.service?'Required service stop':id===l.start?'Tram depot':id===l.end?(l.destination||'Festival gate'):stop?stop.name:id===l.switch?'Signal hut':id===l.gate?'Bridge':l.blocked.includes(id)?'Closed street':l.repairs[id]?'Repair site':'Street';}
 // Stable display coordinates preserve the existing puzzle graph and saved routes.
 function point(l,id){
  if(!l.economyVersion&&l.id==='first-light')return [[19,25],[32,28],[44,28],[57,32],[70,38],[87,31],[19,43],[32,45],[44,44],[57,49],[70,55],[86,52],[10,35],[30,54],[43,55],[57,57],[75,60],[93,39],[13,60],[31,64],[44,63],[57,66],[72,68],[86,66],[17,77],[31,76],[44,78],[57,79],[71,80],[86,80]][id];
  const c=id%l.cols,r=Math.floor(id/l.cols),x=12+c*77/(l.cols-1)+(r%2?1.2:-1.2),y=23+r*56/(l.rows-1)+(c%2?1.8:-1.8);
  return [x,y];
 }
 function poly(l,path){return path.map(id=>{const [x,y]=point(l,id);return `${x*10},${y*6.667}`;}).join(' ');}
 function choices(l,d){const last=d.path.at(-1);return last===l.end?[]:Array.from({length:l.cols*l.rows},(_,id)=>id).filter(id=>E.adjacent(l,last,id)&&!l.blocked.includes(id)&&!d.path.includes(id)&&(id!==l.obstruction||E.obstacleOK(l,d.obstacle)));}
 function choiceArrows(l,d){
  const [sx,sy]=point(l,d.path.at(-1)).map((v,i)=>v*(i?6.667:10));
  return choices(l,d).map(id=>{
   const [tx,ty]=point(l,id).map((v,i)=>v*(i?6.667:10)),dx=tx-sx,dy=ty-sy,length=Math.hypot(dx,dy),ux=dx/length,uy=dy/length;
   const x=sx+dx*.68,y=sy+dy*.68;
   return `<path class="connection-choice" data-connection-choice="${id}" d="M${sx+dx*.3},${sy+dy*.3} L${x},${y} M${x-ux*8-uy*5},${y-uy*8+ux*5} L${x},${y} L${x-ux*8+uy*5},${y-uy*8-ux*5}"/>`;
  }).join('');
 }
 function routeSVG(l,path,small=false,arrows=''){
  const roads=[];for(let a=0;a<l.cols*l.rows;a++)for(const b of [a+1,a+l.cols])if(b<l.cols*l.rows&&E.adjacent(l,a,b))roads.push(`<polyline points="${poly(l,[a,b])}" class="${l.blocked.includes(a)||l.blocked.includes(b)?'closed-road':'open-road'}"/>`);
  const history=state().history.filter(r=>r.level===l.id);const previous=showTrace&&history.length?[{path:history[0].firstPlan},{path:history.at(-1).path}]:[];
  return `<svg class="route-lines ${small?'mini-route':''}" viewBox="0 0 1000 666.7" preserveAspectRatio="none" aria-hidden="true"><g class="town-roads">${roads.join('')}</g><g class="connection-choices">${arrows}</g>${previous.map((r,i)=>`<polyline class="previous-route previous-${i}" points="${poly(l,r.path)}"/>`).join('')}<polyline class="route-outline" points="${poly(l,path)}"/><polyline class="route-plan" points="${poly(l,path)}"/><polyline class="tram-trail" points="${poly(l,path)}"/></svg>`;
 }
 function board(l,d,r,preview=false){
  const last=d.path.at(-1),marker=r?d.path[r.stopIndex??E.evaluate(l,d.path,r.journeyVersion===2?r.puzzle:undefined).stopIndex]:l.start,[mx,my]=point(l,marker);
  return `<div class="rescue-board ${!preview&&E.obstacleOK(l,d.obstacle)?'route-open':''} ${r?.success?'board-won':''}" style="--cols:${l.cols};--rows:${l.rows}" role="group" aria-label="${esc(l.name)} route board. Use arrow keys to move, Enter to connect a street."><img class="town-backdrop" src="assets/festival-town.png" alt="" width="1536" height="1024">${routeSVG(l,d.path,false,!preview&&!r?.success&&E.obstacleOK(l,d.obstacle)?choiceArrows(l,d):'')}<div class="street-grid">${Array.from({length:l.cols*l.rows},(_,id)=>{
   const stop=l.stops.find(s=>s.at===id),obstruction=id===l.obstruction&&!E.obstacleOK(l,d.obstacle),blocked=l.blocked.includes(id),selected=d.path.includes(id),near=!preview&&E.adjacent(l,last,id)&&!blocked&&!obstruction&&!selected&&last!==l.end,[x,y]=point(l,id);
   const art=obstruction?'<span class="repair-lock">?</span>':id===l.obstruction?icon('check'):id===l.service?icon('bolt'):id===l.start?icon('tram'):id===l.end?icon('flag'):stop?window.TryvoArt.portrait():id===l.switch?icon('bolt'):id===l.gate?'<span class="bridge-glyph">≋</span>':blocked?'<span class="closure-mark">!</span>':'<span class="street-dot"></span>';
   return `<button class="street ${!preview&&id===last?'current-route-end':''} ${selected?'on-route':''} ${near?'connectable':''} ${blocked?'street-closed':''} ${obstruction?'repairable-obstruction':id===l.obstruction?'repaired-obstruction':''} ${id===l.service?'service-stop':''} ${stop?'pickup':''} ${id===l.start?'depot':''} ${id===l.end?'festival-gate':''} ${id===l.switch?'signal-hut':''} ${id===l.gate?'river-bridge':''}" style="left:${x}%;top:${y}%" data-rescue="cell" data-cell="${id}" aria-label="Row ${Math.floor(id/l.cols)+1}, column ${id%l.cols+1}: ${label(l,id)}${obstruction?', click to solve and reopen':blocked?'':', cost '+E.cellCost(l,id)}${selected?(id===last?', current route end':', on your route'):near?', available next connection':''}" aria-pressed="${selected}" ${blocked?'aria-disabled="true"':''} tabindex="${id===(focusCell??l.start)?0:-1}"><span class="cell-art">${art}</span>${l.repairs[id]?`<small class="repair-cost">${l.repairs[id]}</small>`:''}${(stop||id===l.start||id===l.end||id===l.switch||id===l.service||id===l.obstruction)?`<span class="cell-tag">${obstruction?'Repair shortcut':id===l.obstruction?'Reopened':id===l.service?'Service':id===l.start?'Depot':id===l.end?(l.destination||'Festival'):id===l.switch?'Signal':stop.people+' riders'+(stop.fare?' · '+stop.fare+'/person':'')}</span>`:''}</button>`;
  }).join('')}</div><div class="moving-tram" style="left:${mx}%;top:${my}%" aria-hidden="true">${Array.from({length:l.carriages||1},()=>icon('tram')).join('')}</div></div>`;
 }
 function contribution(l,d){const history=state().history.filter(r=>r.level===l.id),last=history.at(-1);return `<div class="contribution-mini"><div class="contribution-title"><strong>Your attempt</strong><span>${history.length} ${history.length===1?'test run':'test runs'}</span></div><div class="attempt-line"><i></i><span>Current plan</span><b>${E.cost(l,d.path)} credits</b></div>${last?`<div class="attempt-line previous"><i></i><span>First submitted plan</span><b>${E.cost(l,history[0].firstPlan)} credits</b></div><div class="attempt-line latest"><i></i><span>Last tested plan</span><b>${last.cost} credits</b></div><p>${last.success?'All riders arrived.':esc(last.message||E.evaluate(l,last.path).message)}</p>${button(showTrace?'Hide earlier routes':'Compare earlier routes','compare','aria-pressed="'+showTrace+'"',true)}`:'<p>Your first test run starts the record. Every revision is yours.</p>'}<p class="guidance-label">${d.hint?'Nudge opened for this plan':'No in-game guidance opened for this plan'}</p></div>`;}
 function resultCard(l,d,r){const evaluated=r;return `<section class="run-outcome ${r.success?'outcome-won':'outcome-retry'}" id="run-outcome" tabindex="-1"><span class="outcome-symbol">${icon(r.success?'star':'refresh')}</span><div><span class="small-label">${r.success?'You made this happen':r.reason==='checkpoint'?'A stop along the way':'A useful test run'}</span><h2>${r.success?'Journey complete.':r.reason==='checkpoint'?'Settle your final dispatch.':'Your plan has one more turn in it.'}</h2><p>${esc(evaluated.message)}</p><div class="outcome-actions">${r.success?'':button('Keep building','keep')+' '+button('Start a fresh route','clear','',true)}</div>${r.economyVersion===1?`<p class="route-earnings">${r.revenue} fares − ${r.cost} cost = ${r.net} operating net${r.success?` · rebate +${r.rebate} · final balance ${r.settledBalance}`:''} · +${r.awarded||0} points this run</p>`:''}${r.success?C.handoff(host.getState(),l.id):''}<details class="outcome-full-report"><summary>View my decisions and feedback</summary>${Q.receipt(r)}<details class="route-receipt"><summary>Your contribution · ${r.path.length-1} connected streets</summary><p>${r.moves} route edits. ${r.cost} credits used. ${r.hint?'Guidance was opened.':'No in-game guidance opened.'} Your first submitted plan had ${r.firstPlan.length-1} streets; your recorded route has ${r.path.length-1}.</p>${button('Replay my tram journey','replay',`data-record="${r.id}"`,true)}<p class="caption">A game achievement in this layout, not a measure of general intelligence.</p></details></details></div></section>`;}
 // Review submissions clear lastId; keep an arrival identity scoped to this draft.
 function arrivalRecord(l,d){
  const key=JSON.stringify([d.path,d.boarding]);
  return state().history.findLast(r=>r.id===(d.arrivalId||d.lastId)&&r.level===l.id&&r.reason==='checkpoint'&&r.moves===d.moves&&JSON.stringify([r.path,r.boarding])===key)||null;
 }
 function direction(l,d,r){
  let stage=0,status='case',title='Start with the client case',copy='Your recommendation reopens the shortcut. Read the brief and make your own first judgment.',action='obstacle',label='Open the client case';
  if(r?.success){stage=3;status='complete';title='You made it happen. Now look back.';copy='Review the decisions you made and what changed along the way. Your next chapter is below.';}
  else if(!E.obstacleOK(l,d.obstacle)){
   if(d.obstacle.case?.initial?.trim()){title='Continue your client case';copy='Your draft is saved. Pick up your judgment, evidence or recommendation where you left off.';label='Continue the client case';}
  }else if(arrivalRecord(l,d)){
   stage=2;
   if(E.evaluate(l,d.path,d.puzzle,d).success){status='finish';title='Your arrival decision is ready';copy='Finish this journey to record the arrival, then review your choices.';action='finish-journey';label='Finish my journey';}
   else{status='arrival';title='One last decision at arrival';copy='New information has arrived. Respond to the twist to finish this journey.';action='checkpoint';label='Continue the arrival decision';}
  }else{
   stage=1;action='show-connections';label='Show my next connections';
   const result=E.evaluate(l,d.path,d.puzzle,d);
   if(result.success||result.reason==='checkpoint'){status='run';title='Your route is ready to run';copy='Test the route you built. At the festival, you’ll respond to a new development.';action='run';label='Run my tram';}
   else if(result.reason!=='unfinished'){status='revise';title='Give your route another look';copy=result.message;label='Show my route';}
   else{status='build';title=d.path.length===1?'Connect your first street':'Keep connecting to the festival';copy='Start from the current route end. Arrows show every available next connection, not a suggested solution. Tap an earlier street or Undo to revise.';}
  }
  const names=['Make a call','Connect the route','Respond & reflect'];
  return `<section class="journey-direction" data-guidance-state="${status}" aria-labelledby="journey-next-title"><ol class="journey-steps" aria-label="Your journey progress">${names.map((name,i)=>`<li class="${i<stage?'is-done':i===stage?'is-current':''}" ${i===stage?'aria-current="step"':''}><b aria-hidden="true">${i<stage?'✓':i+1}</b><span>${i<stage?'<span class="sr-only">Completed: </span>':''}${name}</span>${i<2?'<i aria-hidden="true">→</i>':''}</li>`).join('')}</ol><div class="journey-next"><span class="next-direction-arrow" aria-hidden="true">↳</span><div><p class="next-eyebrow">${stage===3?'JOURNEY COMPLETE':'YOUR NEXT MOVE'}</p><h2 id="journey-next-title">${esc(title)}</h2><p>${esc(copy)}</p></div>${stage===3?'<a class="button" href="#progress">See my decisions <span aria-hidden="true">→</span></a>':`<button class="button" data-journey-action="${action}">${label}<span aria-hidden="true">→</span></button>`}</div></section>`;
 }
 function render(){
  const {s,l,d}=current(),index=E.levels.indexOf(l),r=s.history.find(r=>r.id===d.lastId&&r.journeyVersion===3),spent=E.cost(l,d.path),best=E.best(s,l.id),f=E.finance(l,d);
  return `<section class="rescue-page"><div class="rescue-top"><a href="#explore">← All journeys</a><span>Level ${index+1} / 12 · ${index<4?'Learn the line':index<8?'Run the service':'Master the network'}</span><button class="text-button" data-rescue="help">How to play</button></div><div class="rescue-heading"><div><h1>${esc(l.name)}</h1><p>${l.fares?`Deliver at least ${l.minPassengers} riders within ${l.distanceLimit} km. Choose pickups that fit your ${l.capacity} seats.`:`Bring ${l.minPassengers} riders to the festival within ${l.distanceLimit} km. Repair the shortcut to make your budget last.`}</p></div><div class="tram-spec"><span>${Array.from({length:l.carriages},()=>icon('tram')).join('')}</span><strong>${l.carriages} car${l.carriages>1?'s':''} · ${l.capacity} seats</strong><small>${l.unit} travel credit${l.unit>1?'s':''} / km</small></div></div>
  ${direction(l,d,r)}<div class="route-wallet simple-wallet" aria-label="Live route preview"><div><span>Distance planned</span><strong class="${f.distance>l.distanceLimit?'is-negative':''}">${f.distance} / ${l.distanceLimit}<small> km</small></strong></div><div><span>Riders on route</span><strong class="${f.passengers>l.capacity?'is-negative':''}">${f.passengers} / ${l.capacity}<small> seats</small></strong></div><div><span>${r?.success?'Credits after arrival':'Credits left'}</span><strong class="${f.balance<0?'is-negative':''}">${f.balance+(r?.success?r.rebate:0)}</strong></div></div><details class="route-cost-details"><summary>How the budget works</summary><dl><div><dt>Starting credits</dt><dd>${l.budget}</dd></div><div><dt>Passenger fares</dt><dd>+${f.revenue}</dd></div><div><dt>Travel, repairs and boarding</dt><dd>−${f.cost}</dd></div><div><dt>Earned benefits</dt><dd>+${f.bonus+(r?.success?r.rebate:0)}</dd></div><div><dt>Credits left</dt><dd>${f.balance+(r?.success?r.rebate:0)}</dd></div></dl><p>Fares arrive when riders board. You must pay for each street before collecting its fares.${l.fares?` Keep spending after fares within ${-l.profitTarget} credits. Current spending after fares: ${f.cost-f.revenue}.`:''}</p></details>
  <div class="rescue-layout"><div class="board-panel"><div class="map-stage"><div class="board-toolbar"><span class="map-title">${icon('tram')} Festival Rescue</span><span class="map-rate">${l.unit} credit${l.unit>1?'s':''} per km</span></div><div class="map-scroll ${fitTown?'fit-town':''}">${board(l,d,r)}</div><div class="map-bottom"><div class="board-key"><span><i class="key-route"></i>Your route</span><span>◆ Repair shortcut</span><span>! Permanent closure</span></div><div class="board-actions">${button(icon('undo')+'Undo','undo',d.path.length<2?'disabled':'',true)}${button(icon('play')+(r?'Test again':'Run tram'),'run',d.path.length<2?'disabled':'')}</div></div><div class="arrival-banner" aria-hidden="true">Arrival and dispatch complete</div></div><div class="mobile-map-tools"><span>Swipe to explore · click the striped repair site</span>${button(fitTown?'Zoom in':'Fit town','fit','',true)}</div><div class="board-feedback"><p class="board-message" id="rescue-message" role="status">${esc(flash||(r?.success?'Journey completed. Replay to compare another route; earned points are kept.':f.overAt!==null?'Cash warning: you cannot pay an earlier street using fares collected later.':f.capacityAt!==null?'Capacity warning: skip a group or change the route.':f.distance>l.distanceLimit?'Distance warning: this plan exceeds the dispatch allowance.':d.obstacle.solved?'Shortcut reopened. Connect adjacent streets, choose your pickups, then run the tram.':'Click the striped obstruction to repair the short route. Then connect streets from the depot.'))}</p>${button('Clear route','clear',d.path.length<2?'disabled':'',true)}</div><p class="map-rule">Each connection is 1 km. ${l.mode==='discount'?'The repaired connection also costs a 1-credit toll.':''} ${l.service!==null?'The service stop is mandatory for this larger tram.':''} Extra fare cannot buy a longer distance allowance.</p></div>
  <aside class="dispatch-panel"><section class="journey-checkpoint ${d.obstacle.solved?'compact-repair':''}"><span class="small-label">${d.obstacle.solved?'✓ Shortcut reopened':'A decision unlocks this shortcut'}</span>${d.obstacle.solved?`<p>${d.obstacle.firstPass?'First-try bonus: +1 credit.':'The direct connection is ready.'}</p>`:`<h3>${esc(window.TryvoCaseData[l.id].title)}</h3><p>Investigate a fictional client case and defend your recommendation to reopen the ${l.optimalDistance} km route.</p>`}${button(d.obstacle.solved?'Review decision':'Open client case','obstacle','',true)}</section><section class="passenger-choices"><h3>${l.fares?'Choose your pickups':'Your passengers'}</h3><p>${l.fares?'Tick a group to collect them when your route reaches their stop. Untick to pass without boarding.':'Stop at the rider marker to collect this group.'}</p>${l.stops.map(x=>`<label>${l.fares?`<input type="checkbox" data-boarding="${x.at}" ${d.boarding[x.at]!==false?'checked':''}>`:icon('people')}<span><strong>${esc(x.name)} · ${x.people} people</strong><small>${x.fare?x.people+' × '+x.fare+' = '+x.people*x.fare+' fare credits'+(x.boardingFee?' · '+x.boardingFee+' boarding fee':''):'Required pickup · no fare'}${d.path.includes(x.at)?' · On route':''}</small></span></label>`).join('')}</section><details class="route-rules"><summary>What makes a successful trip?</summary><p>Carry ${l.minPassengers}+ passengers, stay within ${l.capacity} seats and ${l.distanceLimit} km, and pay each street before collecting its fare.${l.fares?' Operating net must be at least '+l.profitTarget+' credits.':''} ${l.service!==null?'Visit the service stop.':''} Finish the final dispatch at arrival.</p><p>First-try repair: +1 credit. Correct final dispatch: 1-credit rebate, or 2 on the first try without a nudge. These are separate from game points.</p>${button('Show route nudge','hint','',true)}${d.hint?`<p>${esc(l.hint)}</p>`:''}</details><details class="route-rules"><summary>Your route record</summary>${contribution(l,d)}</details></aside>${r?resultCard(l,d,r):''}</div><p class="rescue-footnote">Travel credits are a simulated operating budget. Game points measure achievements in this game.</p></section>`;
 }
 function journal(){const s=state(),done=E.levels.filter(l=>E.completed(s,l.id)).length;if(!s.history.length)return '';return `<section class="rescue-journal"><div><span class="festival-label">The city remembers</span><h2>${done} of 3 festival routes restored</h2><p>${s.history.length} test runs. Every revision was part of getting there.</p></div><div class="rescue-best-list">${E.levels.map(l=>{const b=E.best(s,l.id);return `<div><span>${esc(l.name)}</span><strong>${b?b.cost+' credits':'Not restored'}</strong></div>`;}).join('')}</div><a class="rescue-button rescue-secondary" href="#rescue">Return to the festival ↗</a></section>`;}
 function records(){const s=state();if(!s.history.length)return '';return `<details class="rescue-records"><summary>Festival Rescue · your route records</summary><p>Best successful route per layout. Fewer credits wins within the same layout. No live players or universal ability ranking.</p><div class="route-record-grid">${E.levels.map(l=>{const b=E.best(s,l.id);return `<article><h3>${esc(l.name)}</h3>${b?`<strong>${b.cost}<small> / ${l.budget} credits</small></strong><p>${b.path.length-1} streets · ${b.moves} edits${b.hint?' · Guidance opened':''}</p>${button('Inspect my route','watch-best',`data-level="${l.id}"`,true)}`:'<p>Complete this layout to set a record.</p>'}</article>`;}).join('')}</div></details>`;}
 function paint(focus){const scroll=document.querySelector('.map-scroll')?.scrollLeft||0;host.render(false);const map=document.querySelector('.map-scroll');if(map)map.scrollLeft=scroll;if(focus!==undefined){const el=document.querySelector(`[data-cell="${focus}"]`);el?.focus({preventScroll:true});}}
 function message(text){flash=text;const el=document.querySelector('#rescue-message');if(el)el.textContent=text;else host.toast(text);}
 function animate(l,r,notify=false){
  cancel();playing=true;
  document.querySelector('.rescue-board')?.classList.add('is-running');
  document.querySelectorAll('.rescue-page [data-rescue],.rescue-page [data-journey-action],.rescue-page [data-boarding]').forEach(b=>b.disabled=true);
  const route=r.path.slice(0,r.stopIndex+1),start=resumeAt!==null?Math.max(0,route.indexOf(resumeAt)):0;
  resumeAt=null;
  const points=route.slice(start).map(at=>{const [x,y]=point(l,at),stop=l.stops.find(s=>s.at===at);return {x,y,at,pause:stop&&r.boarding?.[at]!==false||at===l.switch?240:0};});
  const marker=document.querySelector('.moving-tram');
  message('Your tram is testing the route…');
  travel=window.TryvoTravel.play({marker,points,onArrive:({at},i)=>{
   document.querySelector(`[data-cell="${at}"]`)?.classList.add('tram-visited');
   const trail=document.querySelector('.rescue-board .tram-trail');
   if(trail)trail.setAttribute('points',poly(l,route.slice(0,start+i+1)));
   const stop=l.stops.find(s=>s.at===at);
   if(stop&&r.boarding?.[at]!==false)message(`${stop.people} ${stop.name.toLowerCase()} are aboard. Your route keeps going.`);
   else if(at===l.switch)message('Signal sent. The bridge is now open for your tram.');
  },onComplete:()=>{
   playing=false;flash=r.message;paint();
   const out=document.querySelector('#run-outcome');out?.focus({preventScroll:true});
   if(notify){if(r.reason==='checkpoint')openCheckpoint(l,current().d);else window.TryvoFeedback.route(l,r);}
   if(!document.querySelector('#dialog').open)out?.scrollIntoView({behavior:window.TryvoTravel.enabled()?'smooth':'instant',block:'nearest'});
  }});
 }

 function openCheckpoint(l,d){window.TryvoCases.open(l,d,'arrival',{...host,submit:result=>E.submit(state(),l,d,'arrival',result),offline:()=>offlineCheckpoint(l,d),isCurrent:()=>host.getState().tram?.drafts[l.id]===d,continue:()=>{const last=state().history.at(-1);resumeAt=last?.level===l.id&&last.reason==='checkpoint'&&JSON.stringify(last.path)===JSON.stringify(d.path)?l.checkpoint:null;paint();handle('run',{});}});}
 function openObstacle(l,d){window.TryvoCases.open(l,d,'obstacle',{...host,submit:result=>E.submit(state(),l,d,'obstacle',result),offline:()=>offlineObstacle(l,d),isCurrent:()=>host.getState().tram?.drafts[l.id]===d,continue:()=>{paint();message('Your recommendation reopened the shortcut. Connect the repaired street from a neighbouring junction.');}});}
 function offlineCheckpoint(l,d){Q.open({...l,puzzle:E.arrivalPuzzle(l,d)},d,{...host,submit:result=>E.submit(state(),l,d,'arrival',result),paint:()=>paint(),continue:()=>{const last=state().history.at(-1);resumeAt=last?.level===l.id&&last.reason==='checkpoint'&&JSON.stringify(last.path)===JSON.stringify(d.path)?l.checkpoint:null;paint();handle('run',{});}});}
 function offlineObstacle(l,d){Q.open({...l,puzzle:E.obstaclePuzzle(l)},{puzzle:d.obstacle,lastId:null},{...host,submit:result=>E.submit(state(),l,d,'obstacle',result),save:()=>{d.lastId=null;host.save();},paint:()=>paint(),continue:()=>{paint();message('Shortcut reopened. Connect the repaired street from a neighbouring junction.');}});}
 function handle(action,b){const {s,l,d}=current();if(playing)return;
  if(action==='show-connections'){const end=document.querySelector(`[data-cell="${d.path.at(-1)}"]`);end?.focus({preventScroll:true});end?.scrollIntoView({block:'center',inline:'center',behavior:window.TryvoTravel.enabled()?'smooth':'instant'});return;}
  if(action==='finish-journey'){if(!arrivalRecord(l,d)||!E.evaluate(l,d.path,d.puzzle,d).success)return;resumeAt=l.end;handle('run',{});return;}
  if(action==='obstacle'){openObstacle(l,d);return;}
  if(action==='checkpoint'){if(!d.path.includes(l.checkpoint)){message('Connect the checkpoint to your route first.');return;}openCheckpoint(l,d);return;}
  if(action==='fit'){fitTown=!fitTown;paint();document.querySelector('[data-rescue=fit]')?.focus({preventScroll:true});return;}
  if(action==='compare'){showTrace=!showTrace;paint();document.querySelector('[data-rescue=compare]')?.focus({preventScroll:true});return;}
  if(action==='enter'){const next=E.level(b.dataset.level);if(!next||!E.unlocked(s,next.id)||!C.available(host.getState(),next.id)){host.toast('Continue the earlier chapters in your Lantern Festival first.');return;}s.selected=next.id;showTrace=false;focusCell=next.start;flash='';host.save();host.navigate('#rescue');return;}
  if(action==='cell'){const id=Number(b.dataset.cell);if(id===l.obstruction&&!E.obstacleOK(l,d.obstacle)){openObstacle(l,d);return;}focusCell=id;try{if(E.edit(l,d,id)){delete d.arrivalId;const f=E.finance(l,d);flash=`${label(l,id)} connected. ${f.distance} km, ${f.passengers} passengers, ${f.balance} projected credits remaining.`;host.save();paint(id);}}catch(e){message(e.message);}return;}
  if(action==='undo'){if(d.path.length>1){d.path.pop();d.moves++;d.lastId=null;delete d.arrivalId;flash='Last street removed.';host.save();focusCell=d.path.at(-1);paint(focusCell);}return;}
  if(action==='clear'){s.drafts[l.id]=E.draft(l);focusCell=l.start;flash='A fresh route. Your earlier test runs are still recorded.';host.save();paint(focusCell);return;}
  if(action==='hint'){d.hint=true;d.lastId=null;host.save();paint();document.querySelector('.rescue-nudge')?.scrollIntoView({block:'nearest'});return;}
  if(action==='help'){host.modal('Your route. Your call.',`<p>Start at the depot marker. Connect a neighbouring street by tapping it or using arrow keys and Enter. The solid line shows your route; a dashed line follows the tram simulation.</p><p>Click the striped obstruction to open a fictional client case. Record your first take, inspect evidence, ask the AI client questions and defend a recommendation to reopen the efficient route. An offline route exercise is also available. Every connection is 1 km; the tram specification shows its cost. Later levels let you choose passenger groups: collect fares on boarding, pay any boarding fees, and stay within seat and distance limits. Visit the service stop when shown. At arrival, respond to a new development in the same case for a credit rebate. AI review considers your decision, evidence, trade-offs and next test; it does not measure intelligence.</p><p>Tap an earlier point on your route to cut back, or use Undo. Run your route to see what happens. There is no timer or penalty for trying again.</p>`);return;}
  if(action==='run'){if(d.path.length<2)return;const previous=s.history.find(r=>r.id===d.lastId);if(l.destination&&previous&&previous.destination!==l.destination)d.lastId=null;const previousId=d.lastId,r=E.run(s,l,d);if(r.reason==='checkpoint')d.arrivalId=r.id;if(l.destination&&!r.destination)r.destination=l.destination;host.save();animate(l,r,r.id!==previousId||r.reason==='checkpoint');return;}
  if(action==='replay'){const r=s.history.find(r=>r.id===b.dataset.record);if(r)animate(l,r);return;}
  if(action==='keep'){document.querySelector('.rescue-board')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});focusCell=d.path.at(-1);document.querySelector(`[data-cell="${focusCell}"]`)?.focus({preventScroll:true});return;}
  if(action==='watch-best'||action==='watch-record'){const r=action==='watch-record'?[...s.history,...(host.getState().rescue?.history||[])].find(x=>x.id===b.dataset.record):E.best(s,b.dataset.level);if(!r)return;const original=r.economyVersion===1?E.level(r.level):E.Legacy.level(r.level),layout=r.destination?{...original,destination:r.destination}:original,preview=board(layout,{path:r.path,obstacle:r.obstacle},r,true).replaceAll('data-rescue="cell"','disabled').replaceAll('tabindex="0"','tabindex="-1"').replace('Use arrow keys to move, Enter to connect a street.','Recorded route preview.');host.modal(esc(layout.name)+(action==='watch-record'?' · recorded test run':' · your best route'),`<p>${r.cost} route credits · ${r.path.length-1} km. ${r.economyVersion===1?`Fares ${r.revenue} · net ${r.net}.`:``} ${r.hint?'Guidance opened.':'No in-game guidance opened.'}</p>${preview}${Q.receipt(r)}<p>This is your recorded route. Your current working route is unchanged.</p>`);document.querySelector('#dialog').addEventListener('close',()=>document.querySelector('#dialog .rescue-board')?.remove(),{once:true});return;}
  if(action==='celebrate'){host.modal('Your Lantern Festival',C.finale(host.getState()));return;}
  if(action==='legacy-celebrate'){host.modal('You brought the city together.',`${scene(true)}<h3>Three routes. One festival.</h3><p>You found a way around the closure, picked up two groups, and opened the river crossing. Every arrival followed a route you designed.</p><p>Revisit a chapter to try a more efficient route, or explore a different kind of thinking in the original missions.</p><a class="rescue-button" href="#mission-library" data-rescue="leave-modal">Explore another challenge ↗</a>`);return;}
  if(action==='leave-modal'){document.querySelector('#dialog').close();}
 }
 document.addEventListener('change',ev=>{const input=ev.target.closest('[data-boarding]');if(!input||!host)return;const {d}=current();d.boarding[input.dataset.boarding]=input.checked;d.lastId=null;delete d.arrivalId;d.puzzle.solved=false;host.save();paint();});
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-rescue],[data-journey-action]');if(!b||!host)return;handle(b.dataset.rescue||b.dataset.journeyAction,b);});
 document.addEventListener('keydown',ev=>{const b=ev.target.closest('[data-cell]');if(!b||playing)return;const {l}=current(),id=Number(b.dataset.cell),col=id%l.cols,row=Math.floor(id/l.cols);let next=id;if(ev.key==='ArrowRight')next=row*l.cols+Math.min(l.cols-1,col+1);else if(ev.key==='ArrowLeft')next=row*l.cols+Math.max(0,col-1);else if(ev.key==='ArrowDown')next=Math.min(l.rows-1,row+1)*l.cols+col;else if(ev.key==='ArrowUp')next=Math.max(0,row-1)*l.cols+col;else if(ev.key==='Home')next=row*l.cols;else if(ev.key==='End')next=row*l.cols+l.cols-1;else return;ev.preventDefault();focusCell=next;document.querySelectorAll('[data-cell]').forEach(el=>el.tabIndex=Number(el.dataset.cell)===next?0:-1);document.querySelector(`[data-cell="${next}"]`)?.focus();});
 return {configure,cancel,home,render,journal,records,scene,enter:id=>handle('enter',{dataset:{level:id}})};
})();
